// The writer classes.
const (
	// WriterRequest (H): A request a component served for a caller, recorded by
	// that component: snowplow for a person's or an agent's request, authn for a
	// login and a /delegate token.
	WriterRequest Writer = "request"
	// WriterGateway (G): The agent gateway's hop record, projected by the
	// collector.
	WriterGateway Writer = "gateway"
	// WriterAction (T): An agent's per-action record, written by whatever performs
	// the action.
	WriterAction Writer = "action"
	// WriterController (C): A controller reconcile.
	WriterController Writer = "controller"
)

// The conditions the checker evaluates on a record.
const (
	// CondK8sTarget: The record names a Kubernetes object: k8s.namespace.name or
	// any krateo.audit.object_ref.* key is present.
	CondK8sTarget Condition = "k8s_target"
	// CondWrite: krateo.audit.verb is a write: create, update, patch, delete,
	// deletecollection (a Kubernetes object), post or put (anything else).
	CondWrite Condition = "write"
	// CondMethodOther: http.request.method is _OTHER: the writer was given a
	// method semconv does not name.
	CondMethodOther Condition = "method_other"
	// CondDelegated: The record carries a delegation: krateo.audit.delegation or
	// krateo.audit.on_behalf_of.user.name is present.
	CondDelegated Condition = "delegated"
	// CondImpersonated: The record carries an impersonation: either
	// krateo.audit.impersonated_user.* key is present.
	CondImpersonated Condition = "impersonated"
	// CondCaused: The record names the object a controller reconciled: any
	// krateo.audit.cause_ref.* key is present.
	CondCaused Condition = "caused"
	// CondDenied: krateo.audit.outcome is denied: the writer itself refused.
	CondDenied Condition = "denied"
	// CondContentWrite: krateo.audit.verb creates or replaces an object's content:
	// create or update.
	CondContentWrite Condition = "content_write"
	// CondClientRejected: The writer rejected the client's provenance header:
	// krateo.audit.client.rejected is present.
	CondClientRejected Condition = "client_rejected"
	// CondClientProvenance: The record carries provenance the client asserted: a
	// krateo.audit.client.* key other than source and rejected is present.
	CondClientProvenance Condition = "client_provenance"
	// CondConfirmedSet: The record names the confirmed set its write belongs to:
	// any krateo.audit.client.confirmed_set.* key is present.
	CondConfirmedSet Condition = "confirmed_set"
	// CondEndpointTarget: The record's target is an external endpoint:
	// server.address is present.
	CondEndpointTarget Condition = "endpoint_target"
	// CondSucceeded: krateo.audit.outcome is success: the authority answered and
	// the action completed.
	CondSucceeded Condition = "succeeded"
	// CondKeptExistingValue: krateo.audit.denial_reason is kept_existing_value:
	// the writer declined to overwrite an authorization-bearing value already
	// present.
	CondKeptExistingValue Condition = "kept_existing_value"
	// CondPublicActor: krateo.audit.actor_class is public: the request carried no
	// credential at all, and the writer served it as its configured public
	// identity.
	CondPublicActor Condition = "public_actor"
	// CondIssuedOrAudienceRefused: krateo.audit.outcome is success, or
	// krateo.audit.denial_reason is audience_not_allowed: a token exchange that
	// issued its token, or that refused the requested audience.
	CondIssuedOrAudienceRefused Condition = "issued_or_audience_refused"
)

